/**
 * The fixed part of every generated file: imports, the `@generated` header and the runtime helpers
 * the suites call. Kept as plain text so the golden files show exactly what a project receives.
 */

import type { NodeId } from "@averri/ir";
import { str } from "./emit.js";

export const HEADER_PREFIX = "// @generated by averri ";

export function renderHeader(averriVersion: string, owner: NodeId, hash: string): string {
  return `${HEADER_PREFIX}${averriVersion} from ${owner} hash:${hash} — do not edit`;
}

export interface PreludeInput {
  averriVersion: string;
  owner: NodeId;
  hash: string;
  configImport: string;
  /** Null when the owner needs no app (no entry point configured). */
  entryImport: string | null;
  /** `[alias, specifier]` pairs for declaration modules. */
  modules: Array<[string, string]>;
  fixtures: readonly string[];
  numRuns: number;
  needsCrypto: boolean;
}

export function renderPrelude(p: PreludeInput): string {
  const imports = [
    'import { afterAll, beforeAll, describe, expect, it } from "vitest";',
    'import * as fc from "fast-check";',
    p.needsCrypto ? 'import { createHmac } from "node:crypto";' : null,
    'import { createTestHarness, type AverriTestHarness, type PhaseLike, type PrismaModelLike, type TraceLike } from "@averri/contracts";',
    `import config from ${str(p.configImport)};`,
    p.entryImport ? `import * as entry from ${str(p.entryImport)};` : null,
    ...p.modules.map(([alias, spec]) => `import * as ${alias} from ${str(spec)};`),
  ].filter((l): l is string => l !== null);

  const setup = [
    `const OWNER = ${str(p.owner)};`,
    `const FIXTURES = [${p.fixtures.map((f) => str(f)).join(", ")}] as const;`,
    `const NUM_RUNS = ${p.numRuns};`,
    "/** Property tests drive NUM_RUNS full requests (fixtures, app, contract evaluation) each. */",
    "const PROPERTY_TIMEOUT_MS = 120_000;",
    "",
    "let h: AverriTestHarness;",
    "beforeAll(async () => {",
    `  h = await createTestHarness({ config, app: ${p.entryImport ? "entry" : "null"}, modules: [${p.modules.map(([alias]) => alias).join(", ")}] });`,
    "});",
    "afterAll(async () => {",
    "  await h.close();",
    "});",
  ];

  return [renderHeader(p.averriVersion, p.owner, p.hash), "/* eslint-disable */", ...imports, "", ...setup, "", HELPERS].join("\n");
}

/** Runtime helpers; identical in every generated file. */
export const HELPERS = `// --- helpers (identical in every generated file) ---
type Env = { input: Record<string, unknown>; actor: Record<string, unknown> | null };
type SeedMode = "satisfy" | "falsify";
type Invoked = Awaited<ReturnType<AverriTestHarness["invoke"]>>;
let nonceCounter = 0;
const nonceBase = Date.now() % 1_000_000;
function nonce(): string {
  nonceCounter += 1;
  return \`\${nonceBase.toString(36)}\${nonceCounter.toString(36)}\`;
}
/** Strictly increasing within a file; unique Int columns use (v % 1000) + nonceInt() * 1000 (fits a Prisma Int). */
function nonceInt(): number {
  nonceCounter += 1;
  return nonceBase + nonceCounter;
}
function draw<T>(arb: fc.Arbitrary<T>): T {
  return fc.sample(arb, 1)[0] as T;
}
/** Draw an input the declared Zod schema accepts (the static arbitrary is a heuristic; the schema is the truth). */
function drawInput(h: AverriTestHarness, owner: string, arb: fc.Arbitrary<unknown>): Record<string, unknown> {
  for (const candidate of fc.sample(arb, 50)) {
    if (h.parseInput(owner, candidate).ok) return candidate as Record<string, unknown>;
  }
  // The static arbitrary missed a schema constraint: keep what it drew where the schema agrees, re-sample the rest from the schema.
  for (const candidate of fc.sample(arb, 10)) {
    const conformed = h.conformInput(owner, candidate);
    if (conformed !== null) return conformed;
  }
  throw new Error(\`no input passing the Zod schema of \${owner} could be drawn; the schema needs a constraint averri cannot sample (a refinement or transform)\`);
}
const SEED_MODES: SeedMode[] = ["satisfy", "falsify"];
function model(h: AverriTestHarness, name: string): PrismaModelLike {
  const m = h.prisma[name];
  if (!m) throw new Error(\`Prisma client has no model accessor "\${name}"\`);
  return m;
}
async function ensureRow(m: PrismaModelLike, where: Record<string, unknown>, data: Record<string, unknown>): Promise<Record<string, unknown>> {
  return (await m.findFirst({ where })) ?? (await m.create({ data }));
}
/** The row identified by the unique \`key\` with \`pins\` applied: updated in place when it exists, created otherwise. */
async function ensurePinned(m: PrismaModelLike, key: Record<string, unknown>, pins: Record<string, unknown>, data: Record<string, unknown>): Promise<Record<string, unknown>> {
  const existing = await m.findFirst({ where: key });
  if (existing === null) return m.create({ data });
  await m.updateMany({ where: key, data: pins });
  return (await m.findFirst({ where: key })) ?? existing;
}
function actorField(env: Env, key: string): unknown {
  if (!env.actor) throw new Error(\`fixture has no actor; cannot read actor.\${key}\`);
  return env.actor[key];
}
function get(value: unknown, path: string[]): unknown {
  let cur: unknown = value;
  for (const seg of path) {
    if (cur === null || typeof cur !== "object") return undefined;
    cur = (cur as Record<string, unknown>)[seg];
  }
  return cur;
}
function altered(v: unknown): unknown {
  if (typeof v === "string") return \`\${v}_x\`;
  if (typeof v === "number") return v + 1;
  if (typeof v === "bigint") return v + 1n;
  if (typeof v === "boolean") return !v;
  if (v instanceof Date) return new Date(v.getTime() + 86_400_000);
  return "altered";
}
function bump(v: unknown, delta: number): unknown {
  if (typeof v === "number") return v + delta;
  if (typeof v === "bigint") return v + BigInt(delta);
  if (v instanceof Date) return new Date(v.getTime() + delta * 86_400_000);
  if (typeof v === "string" && !Number.isNaN(Date.parse(v))) return new Date(Date.parse(v) + delta * 86_400_000);
  throw new Error(\`cannot offset \${String(v)} by \${delta}\`);
}
function is2xx(status: number): boolean {
  return status >= 200 && status < 300;
}
function errorBody(res: Invoked): { error?: string; contract?: string } {
  return typeof res.body === "object" && res.body !== null ? (res.body as { error?: string; contract?: string }) : {};
}
function phaseRecord(trace: TraceLike | null, phase: string, contract: string): PhaseLike | undefined {
  return trace?.phases.find((p) => p.phase === phase && p.contract === contract);
}
function emittedCount(trace: TraceLike | null, event: string): number {
  const emit = trace?.phases.find((p) => p.phase === "emit");
  return (emit?.events ?? []).filter((e) => e.event === event).length;
}
function expect2xx(res: Invoked, what: string): void {
  expect(is2xx(res.status), \`\${what}: expected 2xx, got \${res.status} \${JSON.stringify(res.body)}\`).toBe(true);
}
void nonce; void nonceInt; void draw; void drawInput; void SEED_MODES; void model; void ensureRow; void ensurePinned; void actorField; void get; void altered; void bump; void errorBody; void phaseRecord; void emittedCount; void expect2xx; void FIXTURES; void NUM_RUNS; void PROPERTY_TIMEOUT_MS; void OWNER;`;
